for (const [city,rows] of Object.entries({cincinnati:cincy,philadelphia:philly,chicago})) {
  const current = new URL(`../data/${city}/current-weekend.json`, import.meta.url);
  const prior = JSON.parse(await readFile(current,"utf8"));
  const archive = new URL(`../data/archive/${city}/weekend-${prior.weekend.startDate}.json`, import.meta.url);
  await mkdir(new URL(`../data/archive/${city}/`, import.meta.url),{recursive:true});
  await writeFile(archive,`${JSON.stringify(prior,null,2)}\n`);
  const events = rows.map(item);
  for (const event of events) event.featured=featured[city].has(event.id);
  const data={schemaVersion:2,city:cityMeta[city],weekend:{label:"Friday, September 4 – Sunday, September 6, 2026",shortLabel:"Sep 4–6",startDate:"2026-09-04",endDate:"2026-09-06",verifiedAt:cityMeta[city].verifiedAt,updatedAt:cityMeta[city].updatedAt,timezone:cityMeta[city].timezone,defaultDriveMinutes:90,roadTripMaxMinutes:120,refreshTarget:"Wednesday 9:00 AM America/New_York",editionStatus:"verified-upcoming",lastSuccessfulEdition:"September 4–6, 2026"},events};
  await writeFile(current,`${JSON.stringify(data,null,2)}\n`);
  console.log(`${city}: ${events.length} events, ${events.filter(e=>e.featured).length} featured`);
}
